def count_beautiful_indices(arr):
    n = len(arr)
    if n <= 1:
        return 0

    # Build frequency map
    freq_map = {}
    for num in arr:
        freq_map[num] = freq_map.get(num, 0) + 1

    count = 0
    # Check beautiful indices (1-based indexing, so i ranges from 1 to n-2)
    for i in range(n - 1):  # 0-based index
        if arr[i] == freq_map.get(arr[i + 1], 0):
            count += 1

    return count

n = int(input())
if n == 0:
    print(0)
else:
    arr = list(map(int, input().split()))
    print(count_beautiful_indices(arr))
